def slugify(text):
    """Convert text to a URL-friendly slug."""
    result = []
    for char in text.lower():
        if char.isalnum() and (char.isdigit() or char.isalpha()):
            result.append(char)
        elif result and result[-1] != '-':
            result.append('-')
    if result and result[-1] == '-':
        result.pop()
    return ''.join(result).lstrip('-')

