def slugify(text):
    """Convert text to a URL-friendly slug.

    Returns text in lowercase with every run of characters that are not
    a-z or 0-9 replaced by a single '-', and no '-' at either end.
    """
    result = []
    for char in text.lower():
        if char.isalpha() or char.isdigit():
            result.append(char)
        elif result and result[-1] != '-':
            result.append('-')
    if result and result[-1] == '-':
        result.pop()
    return ''.join(result).lstrip('-')

